mapper.select:
		/* selectSample */
			SELECT
				ID, NAME, DESCRIPTION, USE_YN, REG_USER
			FROM SAMPLE
			WHERE ID=#{id}

/* selectSampleList */ SELECT TO_CHAR(FACILITY_ID) AS ID ,TO_CHAR(FACTORY_ID) AS DESCRIPTION ,FACILITY_NAME AS NAME ,'Y' AS USE_YN ,'ADMIN' AS REG_USER FROM FACILITY WHERE 1=1
AND FACILITY_ID LIKE '%' || #{searchKeyword} || '%'
AND FACILITY_NAME LIKE '%' || #{searchKeyword} || '%'
ORDER BY FACILITY_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* selectSampleListXXX */ SELECT ID, NAME, DESCRIPTION, USE_YN, REG_USER FROM SAMPLE WHERE 1=1
AND ID LIKE '%' || #{searchKeyword} || '%'
AND NAME LIKE '%' || #{searchKeyword} || '%'
ORDER BY ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* selectSampleListTotCnt */ SELECT COUNT(*) totcnt FROM SAMPLE WHERE 1=1
AND ID LIKE '%' || #{searchKeyword} || '%'
AND NAME LIKE '%' || #{searchKeyword} || '%'
